def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    aggressive = 0
    weak_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if float(opp.get('hp', 0)) <= 3 or int(opp.get('no_water_days', 0)) >= 1:
                weak_opp += 1
            if float(opp.get('budget', 0)) >= 350:
                rich_opp += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    bid = float(bid)
                    prev_bids.append(bid)
                    if bid >= 100:
                        aggressive += 1

    if not alive:
        return min(budget, 18.0)

    expected_units = supply / float(WATER_REQ)
    scarcity = expected_units < (len(alive) + 1)
    very_tight = expected_units <= max(1.2, (len(alive) + 1) * 0.55)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 3
    elif hp <= 7:
        urgency += 1

    if no_water >= 2:
        urgency += 4
    elif no_water >= 1:
        urgency += 2

    if very_tight:
        urgency += 3
    elif scarcity:
        urgency += 1

    if day >= 8:
        urgency += 1

    base = 16.0
    if urgency <= 1:
        base = 14.0 if not scarcity else 22.0
    elif urgency == 2:
        base = 28.0 if not scarcity else 42.0
    elif urgency == 3:
        base = 48.0 if not scarcity else 66.0
    elif urgency == 4:
        base = 72.0 if not scarcity else 92.0
    elif urgency == 5:
        base = 96.0 if not scarcity else 118.0
    else:
        base = 122.0 if not scarcity else 146.0

    target = base

    if highest_prev > 0:
        if urgency >= 5:
            target = max(target, min(highest_prev + 3.0, 155.0))
        elif urgency >= 3:
            if scarcity:
                target = max(target, min(avg_prev + 4.0, highest_prev * 0.92 + 2.0, 128.0))
            else:
                target = max(target, min(avg_prev * 0.72, 82.0))
        else:
            if aggressive >= 2 or rich_opp >= 2:
                target = min(target, 24.0 if not scarcity else 36.0)
            else:
                target = max(target, min(avg_prev * 0.55, 44.0))

    if weak_opp >= 2 and urgency <= 3:
        target = min(target, 26.0 if not scarcity else 38.0)

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if days_left > 0:
        reserve_floor = min(budget * 0.55, days_left * 18.0)

    cap = budget - reserve_floor
    if urgency >= 5:
        cap = budget
    elif urgency == 4:
        cap = max(cap, budget * 0.55)
    else:
        cap = max(cap, budget * 0.32)

    if hp <= 2 or no_water >= 2:
        cap = budget

    bid = min(target, cap, budget)
    if bid < 0:
        bid = 0.0

    if budget < 25:
        bid = min(budget, max(bid, budget * 0.7 if urgency >= 4 else budget * 0.35))

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opps.append(o)
        except Exception:
            continue

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only (immediate reaction)
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Pressure estimate: if someone was bidding near/above a strong fraction of salary, they likely contest.
    strong_pressure = highest_prev_bid >= (DAILY_SALARY * 0.85)

    # Supply factor: with more supply, winning water is cheaper; with less supply, contest harder.
    # Map supply in [15,25] to [0.2, 1.0]
    if MAX_SUPPLY != MIN_SUPPLY:
        supply_factor = 0.2 + 0.8 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))
    else:
        supply_factor = 0.6
    supply_factor = max(0.2, min(1.0, float(supply_factor)))

    # Base target bid:
    # - If strong pressure, bid higher to avoid falling behind.
    # - Otherwise, bid moderate.
    if strong_pressure:
        target = DAILY_SALARY * (0.45 + 0.25 * supply_factor)
        # If their previous max bid is very high, match slightly below it to reduce overspend.
        if highest_prev_bid > 0:
            target = min(target, highest_prev_bid * 0.95)
    else:
        target = DAILY_SALARY * (0.35 + 0.20 * supply_factor)
        if highest_prev_bid > 0:
            # Stay close enough to beat average contestants.
            target = max(target, highest_prev_bid * 0.55)

    # Urgency adjustments based on my HP and no-water streak
    if my_hp <= 2 or my_no_water_days >= 2:
        target *= 1.35
    elif my_hp <= 4:
        target *= 1.15

    # Ensure we don't try to bid more than budget; also keep a minimum contest bid if we can.
    target = float(target)
    if my_budget <= 0:
        return 0.0

    # Cap to budget with a small safety margin
    bid = min(my_budget, target)

    # If budget is low, still bid enough to avoid immediate death pressure if HP is critical
    if my_hp <= 2:
        bid = max(bid, min(my_budget, DAILY_SALARY * 0.9))

    # Final clamp
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_max = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_max = max(yesterday_max, prev['bid'])
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    if yesterday_max == 0:
        if hp <= 2:
            return min(budget, DAILY_SALARY * 0.9)
        else:
            return min(budget, DAILY_SALARY * 0.5)
    else:
        if hp <= 2:
            bid = min(budget, max(DAILY_SALARY * 0.9, yesterday_max + 1.5))
        else:
            bid = min(budget, max(DAILY_SALARY * 0.5, yesterday_max + 0.5))
        if supply >= 22:
            bid = bid * 0.9
        return min(bid, budget)
